  for( int i=0; i<64; i++ ) { fd_ge_ref_comb_select( ent, table[i], digits[i] ); fd_ge_ref_add_affine( acc, acc, ent ); }
  for( int i=0; i<16; i++ ) r[i] = acc[i];
